/* Mentor Inmobiliario Colombia — interfaz educativa local-first, sin dependencias. */
const MODULES = [
 {id:1,title:'Introducción al sector inmobiliario',icon:'⌂',description:'Conoce qué mueve el sector, quiénes participan y qué significa ser propietario.',duration:'15 min · 5 temas',lesson:{title:'Entender el mundo inmobiliario',lead:'Antes de buscar una vivienda, conviene entender qué se está comprando: un inmueble, una relación jurídica y una decisión financiera que se toma en un mercado local.',sections:[['¿Qué es el sector inmobiliario?','Abarca los terrenos y las construcciones, además de las actividades de construir, vender, arrendar, administrar, financiar y valorar inmuebles. Cada barrio puede comportarse de manera distinta: no existe un único “mercado colombiano”.'],['Quiénes participan','Compradores, propietarios y vendedores; inmobiliarias y agentes; constructoras; bancos y entidades de financiación; notarios y oficinas de registro; avaluadores, administradores y autoridades. Cada actor cumple una función distinta.'],['Comprar, vender, arrendar o invertir','Comprar te da derechos sobre un inmueble y trae costos, obligaciones y riesgo. Arrendar te da el uso por un plazo a cambio de un canon, sin transferir la propiedad. Invertir busca un rendimiento y requiere medir ingresos, costos, vacancia y riesgo. Vender transfiere la propiedad y exige acordar precio y condiciones.']],example:'Una pareja que compra un apartamento usado para vivir analiza ubicación, presupuesto, estado físico y títulos. Una persona que compra un apartamento para arrendar añade una estimación de canon, meses vacantes y costos de administración.',concepts:['Inmueble','Mercado local','Propiedad','Arrendamiento','Inversión'],case:'Piensa en un apartamento de segunda mano en tu ciudad. Escribe quién lo vende, quién verifica su situación jurídica, quién puede financiar al comprador y qué costos podrían aparecer además del precio.',summary:'El sector reúne inmuebles, servicios y actores. Una compra combina una decisión financiera con derechos y obligaciones; vivir e invertir requieren análisis distintos.',question:'¿Cuál opción describe mejor la diferencia entre comprar para vivir e invertir?',options:['Para invertir también se evalúan los ingresos y costos que puede producir el inmueble.','Comprar para vivir nunca tiene costos de mantenimiento.','Invertir garantiza que el inmueble aumente de valor.'],answer:0,feedback:'En una inversión se estiman ingresos, gastos, vacancia y riesgos. El aumento de valor no está garantizado.'}},
 {id:2,title:'Mercado inmobiliario colombiano',icon:'⌖',description:'Aprende a comparar zonas, oferta, demanda y precio por metro cuadrado.',duration:'15 min · 5 temas',lesson:{title:'Leer un mercado inmobiliario local',lead:'El precio de una vivienda depende de su ubicación, características, estado y condiciones de negociación. Comparar propiedades parecidas en la misma zona ayuda a formular mejores preguntas.',sections:[['Oferta, demanda y precio','La oferta son los inmuebles disponibles en condiciones comparables; la demanda reúne a quienes podrían comprarlos o arrendarlos. El precio publicado es una aspiración del vendedor, no necesariamente el precio final de transacción.'],['Analizar una ubicación','Revisa tiempos de viaje en tus horarios reales, acceso a transporte y servicios, ruido, seguridad con fuentes locales, riesgos del entorno, planeación urbana y costos de administración. Visita la zona en más de un horario.'],['Precio por metro cuadrado y estrato','Divide precio de referencia por área construida o privada claramente identificada y compara la misma base entre inmuebles. El estrato clasifica inmuebles residenciales para efectos de servicios públicos; no es una medida de calidad, seguridad ni rentabilidad.']],example:'Dos apartamentos en el mismo sector pueden tener distinto precio por metro cuadrado por su antigüedad, área privada, piso, estado, parqueadero, administración o cercanía a obras. No compares solo el estrato.',concepts:['Oferta','Demanda','Precio pedido','Área privada','Estratificación'],case:'Busca tres viviendas en una sola zona. Anota precio, área privada, edad aproximada, parqueadero y administración. Calcula precio / m² y escribe una diferencia que pueda explicar el rango.',summary:'Compara propiedades de una misma zona con áreas equivalentes y datos verificables. El precio publicado orienta, pero no prueba el valor de transacción; el estrato no define calidad ni seguridad.',question:'¿Qué permite comparar mejor el precio por metro cuadrado?',options:['Propiedades de zonas distintas y tamaños distintos sin revisar sus características.','Inmuebles comparables, usando el mismo tipo de área y una zona similar.','La rentabilidad futura exacta de una vivienda.'],answer:1,feedback:'Es un punto de comparación, no una valuación exacta. Mantén zona, tipo de área y características razonablemente comparables.'}},
 {id:3,title:'Finanzas para comprar vivienda',icon:'◉',description:'Construye un presupuesto realista y entiende financiación y costos.',duration:'15 min · 5 temas',lesson:{title:'Saber cuánto puedes destinar',lead:'El precio que un banco podría financiar no equivale a un presupuesto cómodo. Conviene partir de tus ingresos, gastos, ahorro, deudas y estabilidad financiera.',sections:[['Capacidad de pago','Registra ingresos netos y gastos regulares, deudas, ahorro y un fondo para imprevistos. Estima la nueva cuota dentro de este panorama. La aprobación y condiciones dependen de la entidad, el perfil y el inmueble.'],['Cuota inicial y financiación','El valor a financiar suele ser el precio menos los recursos propios y apoyos confirmados. Compara opciones en pesos y UVR, tasa, seguros, plazo, costos, posibilidad de abonos y condiciones contractuales directamente con cada entidad.'],['Costos de adquisición','Además del precio, considera avalúo, estudio de títulos, escrituración, registro, impuestos aplicables, gastos financieros, seguros, mudanza, reparaciones y administración. Los valores cambian por inmueble, ciudad, entidades y normas vigentes: solicita liquidaciones y cotizaciones.']],example:'Si un hogar recibe $8 millones netos y ya paga $1,4 millones en otras deudas, el simulador puede explorar cuotas, pero no determina la aprobación bancaria ni una cuota segura universal. El hogar debe revisar sus gastos reales y un margen para imprevistos.',concepts:['Cuota inicial','Capital financiado','Tasa efectiva anual','UVR','Flujo mensual'],case:'Usa tu presupuesto real o cifras de ejemplo: resta gastos y deudas de los ingresos, separa un ahorro de emergencia y evalúa varias cuotas. ¿Qué ocurre si los gastos suben o cae un ingreso?',summary:'Un presupuesto sostenible considera ingresos netos, gastos, deudas, seguros, costos de cierre y reserva. Compara ofertas en la misma modalidad; la cuota estimada no equivale a aprobación.',question:'¿Qué debes incluir para evaluar si una cuota cabe en tu presupuesto?',options:['Solo el ingreso bruto mensual.','Ingresos, gastos, deudas, seguros y margen para imprevistos.','Únicamente el monto que la entidad ofrece prestar.'],answer:1,feedback:'La capacidad personal depende del flujo completo del hogar y de obligaciones que la cuota bancaria no siempre refleja.'}},
 {id:4,title:'Tipos de vivienda en Colombia',icon:'▱',description:'Distingue VIS, VIP, No VIS, vivienda nueva, usada y sobre planos.',duration:'15 min · 5 temas',lesson:{title:'Reconocer qué tipo de vivienda estás evaluando',lead:'La modalidad de vivienda influye en su regulación, etapa de entrega, financiación y riesgos. Verifica cada condición con la fuente vigente y el contrato específico.',sections:[['VIS, VIP y No VIS','VIS y VIP son categorías definidas dentro de la política de vivienda y sujetas a reglas de precio, localización y periodo aplicables. Los topes y condiciones pueden variar: no uses una cifra antigua como regla universal. No VIS identifica, en términos generales, vivienda que no cumple la definición VIS aplicable.'],['Nueva, usada, en obra o terminada','En vivienda nueva terminada se inspecciona la unidad y se revisan documentos de entrega y garantías. En obra o sobre planos hay riesgo de plazo, financiación del proyecto y especificaciones. La vivienda usada requiere revisar conservación, historial jurídico y posibles obligaciones de propiedad horizontal.'],['Qué comparar','Confirma área privada, acabados y anexos; licencias y condiciones del proyecto cuando apliquen; fecha y condiciones de entrega; servicios; garantías; cargas y costos de administración. Lee la promesa y anexos antes de comprometer dinero.']],example:'Una oferta “sobre planos” describe un proyecto y una compra que puede ocurrir antes de tener la vivienda lista. Revisa fiducia y mecanismos de manejo del dinero, cronograma, condiciones de devolución y qué sucede si el proyecto cambia; pide asesoría jurídica independiente.',concepts:['VIS','VIP','No VIS','Sobre planos','Vivienda usada'],case:'Compara una vivienda usada lista para entregar con un proyecto en construcción. Para cada una anota qué puedes verificar hoy y qué incertidumbres quedan para más adelante.',summary:'VIS, VIP y No VIS dependen de definiciones y reglas vigentes. Vivienda usada, terminada y sobre planos presentan riesgos distintos: confirma documentos, fechas, condiciones y garantías.',question:'¿Cuál es una forma prudente de verificar si un proyecto aplica como VIS?',options:['Usar un tope que recuerdas de años anteriores.','Confirmar definición y reglas vigentes con Minvivienda y revisar los documentos del proyecto.','Asumir que cualquier vivienda nueva es VIS.'],answer:1,feedback:'Los topes y condiciones se actualizan o dependen del caso. Consulta la fuente oficial y la documentación vigente.'}},
 {id:5,title:'Subsidios y beneficios',icon:'✳',description:'Comprueba convocatorias, requisitos y compatibilidades antes de contar con una ayuda.',duration:'15 min · 5 temas',lesson:{title:'Verificar una ayuda de vivienda',lead:'Un programa anunciado o existente no significa que haya cupos, presupuesto, convocatoria abierta o que tu hogar cumpla los requisitos hoy.',sections:[['Qué verificar','Busca la página y norma oficial vigentes, fechas, presupuesto o disponibilidad, criterios del hogar y del proyecto, límites de ingresos, tipo de vivienda, estado del crédito y canal de postulación. Confirma cambios y cierres antes de tomar decisiones.'],['Caja de compensación','Consulta directamente con tu caja las condiciones vigentes del subsidio familiar de vivienda, documentos, convocatoria, reglas de concurrencia y tiempos. Requisitos y procedimientos pueden variar.'],['Presupuesta con cautela','Separa una ayuda confirmada y asignada de una postulación pendiente. No pagues intermediarios por cupos ni firmes basándote en una aprobación supuesta. Pide confirmación escrita al operador oficial.']],example:'Si el cierre financiero de un proyecto depende de un subsidio solicitado, prepara un escenario sin subsidio y otro solo con el apoyo confirmado. No cuentes con una asignación pendiente como dinero disponible.',concepts:['Convocatoria','Postulación','Asignación','Concurrencia','Elegibilidad'],case:'Selecciona una ayuda que te interese. Anota quién la administra, enlace oficial, vigencia consultada, requisitos, canal oficial y qué parte sigue sin confirmar.',summary:'Verifica operador, convocatoria, disponibilidad y requisitos directamente en fuentes oficiales. Solo incorpora al presupuesto una ayuda confirmada y aplicable a tu hogar y proyecto.',question:'¿Cuándo debes incluir un subsidio en tu presupuesto como dinero disponible?',options:['Cuando un vendedor afirma que seguramente te lo darán.','Después de verificar oficialmente los requisitos y contar con una asignación confirmada aplicable al caso.','Siempre que presentes una postulación.'],answer:1,feedback:'Postularse no garantiza asignación. Verifica la convocatoria y confirma la asignación con el operador oficial.'}},
 {id:6,title:'Proceso de adquisición',icon:'➜',description:'Recorre la compra desde la búsqueda inicial hasta la entrega y el registro.',duration:'15 min · 5 temas',lesson:{title:'Avanzar en una compra paso a paso',lead:'Una compra ordenada deja espacio para revisar el inmueble, el presupuesto, los documentos y las condiciones antes de asumir obligaciones.',sections:[['Buscar y revisar','Define necesidades y presupuesto, compara alternativas, visita el inmueble y comprueba áreas, estado, costos de administración y entorno. Pide documentos de la propiedad y de la parte que vende.'],['Negociar, separar y prometer','Aclara precio, forma y fechas de pago, obligaciones, inventario, condiciones de financiación, arras o penalidades y qué sucede ante incumplimiento. La reserva o separación puede tener efectos contractuales: entiende el texto y recibe asesoría antes de firmar.'],['Crédito, escritura, registro y entrega','Coordina aprobaciones, avalúo y documentos con la entidad. La escritura se otorga ante notaría según el proceso. La transferencia del dominio se formaliza con su inscripción en la Oficina de Registro de Instrumentos Públicos. Haz entrega con inventario, lecturas, llaves y acta.']],example:'Antes de consignar una separación, pide el documento completo y verifica beneficiario, plazo de devolución y condiciones. Solicita que un abogado independiente revise la promesa si hay dudas o condiciones especiales.',concepts:['Separación','Promesa','Escritura','Registro','Acta de entrega'],case:'Organiza una lista de hitos entre la visita y la entrega. Para cada paso indica quién lo confirma, qué documento lo prueba y cuál compromiso de dinero o fecha depende de él.',summary:'Una compra ordenada avanza de búsqueda y revisión a negociación, promesa, financiación, escritura, registro y entrega. Confirma documentos, fechas y condiciones antes de comprometer dinero.',question:'¿Qué formalidad permite que la transferencia del dominio quede registrada?',options:['El pago de una suma de separación.','La inscripción del título en la Oficina de Registro de Instrumentos Públicos.','Una conversación de aceptación por chat.'],answer:1,feedback:'La inscripción registral es esencial para publicitar y formalizar la transferencia del dominio. Verifica el procedimiento aplicable.'}},
 {id:7,title:'Aspectos legales',icon:'§',description:'Aprende qué documentos revisar y por qué buscar acompañamiento jurídico.',duration:'15 min · 5 temas',lesson:{title:'Leer la situación jurídica del inmueble',lead:'Una visita o una oferta atractiva no prueban quién puede vender, cuáles cargas existen o si una compraventa será segura.',sections:[['Certificado de tradición y libertad','Identifica el inmueble mediante su matrícula inmobiliaria y revisa el historial de inscripciones: titulares, transferencias, hipotecas, embargos y otros actos registrados. Solicita una versión reciente en el canal oficial de la Superintendencia de Notariado y Registro. El certificado no reemplaza el estudio de títulos.'],['Estudio de títulos','Un profesional revisa títulos y antecedentes, identifica riesgos y propone qué aclarar o subsanar antes de comprar. Verifica identidad y facultades de quienes venden y consistencia de la información con catastro y documentos del negocio.'],['Otras verificaciones','Consulta reglamento, actas y obligaciones de propiedad horizontal; afectación a vivienda familiar y patrimonio de familia; procesos, impuestos o cuotas pendientes; licencia y tradición cuando corresponda. El caso concreto puede requerir asesoría legal y tributaria.']],example:'Si el certificado muestra una hipoteca, no significa automáticamente que no puedas comprar. La cancelación y el pago deben quedar coordinados en documentos y desembolsos verificados por profesionales y entidad financiera.',concepts:['Matrícula inmobiliaria','Certificado de tradición','Estudio de títulos','Hipoteca','Propiedad horizontal'],case:'Con un certificado de ejemplo o una lista de documentos, identifica quién aparece como titular, las inscripciones vigentes y las preguntas que remitirías a un abogado antes de pagar.',summary:'El certificado registral es una pieza del análisis, no una garantía completa. Un estudio de títulos profesional y la revisión de propiedad horizontal ayudan a identificar cargas y riesgos.',question:'¿El certificado de tradición y libertad sustituye un estudio de títulos?',options:['Sí, garantiza por sí solo que toda compraventa es segura.','No; es una fuente clave, pero una revisión profesional examina antecedentes y documentos del caso.','Sí, si el vendedor entrega una copia impresa.'],answer:1,feedback:'El certificado es una pieza importante. Un estudio de títulos revisa antecedentes y documentos para evaluar el caso completo.'}},
 {id:8,title:'Inversión inmobiliaria',icon:'↗',description:'Calcula ingresos, rentabilidades estimadas, flujo de caja y riesgos.',duration:'15 min · 5 temas',lesson:{title:'Evaluar una inversión sin prometer resultados',lead:'Un buen análisis separa datos observados, supuestos y riesgos. La rentabilidad pasada o estimada no garantiza el resultado futuro.',sections:[['Ingresos y rentabilidad bruta','La rentabilidad bruta anual aproximada se estima como canon mensual × 12 / precio de compra. No resta vacancia, administración, reparaciones, seguros, impuestos, costos de compra ni financiación.'],['Rentabilidad neta y flujo de caja','Estima ingresos efectivamente cobrados y resta vacancia, costos operativos e impuestos aplicables. El flujo de caja con deuda además resta cuota y seguros. Documenta cada supuesto: una proyección es un escenario, no un ingreso garantizado.'],['Riesgo y salida','Considera periodos sin arrendatario, reparaciones, morosidad, cambios de tasa, dificultad para vender, costos de transacción, concentración del patrimonio y cambios del entorno. Comprueba si podrías sostener el inmueble en un escenario desfavorable.']],example:'Supón un arriendo anunciado de $2,4 millones y un precio de $360 millones: la rentabilidad bruta anual teórica es 8 %. Todavía hay que descontar los meses sin inquilino, administración, reparaciones, impuestos, seguros y crédito.',concepts:['Canon','Vacancia','Rentabilidad bruta','Rentabilidad neta','Flujo de caja'],case:'Estima un mes sin canon al año, costos de administración y mantenimiento. Compara la rentabilidad bruta y neta aproximada y prueba qué sucede si el inmueble permanece desocupado más tiempo.',summary:'La rentabilidad bruta omite gastos y vacancia. Estima ingresos netos, costos, deuda y riesgos con supuestos explícitos; ni el canon ni la valorización futura están garantizados.',question:'¿Qué describe mejor la rentabilidad bruta por arriendo?',options:['Un resultado garantizado luego de todos los gastos y del crédito.','Una relación inicial entre el ingreso anual teórico y el precio, antes de gastos.','La valorización futura del inmueble.'],answer:1,feedback:'La rentabilidad bruta es un indicador inicial. No descuenta costos, vacancia, impuestos o financiación.'}},
 {id:9,title:'Negociación y análisis',icon:'◇',description:'Compara ofertas y prepara una negociación con señales de alerta claras.',duration:'15 min · 5 temas',lesson:{title:'Negociar con información verificable',lead:'Negociar bien no es presionar: es descubrir condiciones, comparar alternativas y dejar por escrito acuerdos que puedas cumplir.',sections:[['Comparables y propuesta','Usa inmuebles similares en zona, área, estado y fecha. Distingue publicaciones de transacciones verificadas. Documenta reparaciones pendientes y costos previsibles para sustentar tu oferta.'],['Preguntas al vendedor','Pregunta por titularidad, motivo y plazo de venta, gravámenes, paz y salvo de administración, servicios, reformas, entrega, inventario y condiciones de pago. Confirma cada dato con documentos y fuentes independientes.'],['Señales de alerta','Presión para pagar rápido, precio o titular sin documentos, negativa a una revisión independiente, pagos a terceros sin justificación, promesa con espacios, o supuestos subsidios garantizados. Detén la operación hasta aclarar identidad, canal y condiciones.']],example:'Una oferta menor puede justificarse con cotizaciones de reparaciones. Define previamente tu tope real, condiciones y vigencia de la propuesta y no entregues dinero hasta entender el acuerdo y verificar al beneficiario.',concepts:['Inmueble comparable','Oferta','Condición precedente','Señal de alerta','Debida diligencia'],case:'Redacta cinco preguntas para una visita y tres condiciones que deben cumplirse antes de entregar una suma. Evalúa cómo confirmarías cada respuesta.',summary:'Una negociación sólida se apoya en comparables y evidencias. Confirma identidad, titularidad, documentos, condiciones de pago y destinatario antes de firmar o consignar.',question:'¿Qué hacer si te exigen consignar hoy a un tercero para “asegurar” el inmueble?',options:['Consignar una suma pequeña para no perderlo.','Verificar identidad, titularidad, destinatario y documento contractual antes de pagar.','Enviar una foto de tu documento para reservarlo.'],answer:1,feedback:'La prisa y un pago a un tercero son señales que requieren verificación independiente antes de cualquier pago.'}},
 {id:10,title:'Proyecto final',icon:'▣',description:'Integra finanzas, mercado, documentos y negociación en una decisión completa.',duration:'15 min · 5 temas',lesson:{title:'Tu plan de compra informado',lead:'Integra lo aprendido en un expediente de decisión: qué buscas, cuánto puedes destinar, qué comprobaste y qué falta resolver.',sections:[['Plan financiero','Define presupuesto total, dinero disponible, cuota inicial, financiación preevaluada, costos de compra cotizados y reserva para emergencias. Prueba cambios de tasa, ingreso, costos y plazo.'],['Comparación y debida diligencia','Compara tres propiedades con área y ubicación equivalentes, costos recurrentes y estado físico. Para la opción final reúne certificado de tradición actualizado, estudio jurídico, datos de propiedad horizontal, documentos de identidad y soportes financieros.'],['Decisión y siguientes pasos','Deja por escrito por qué compras o esperas, riesgos que aceptas, condiciones que faltan y personas profesionales que revisarían la operación. La decisión puede ser no comprar todavía si el escenario no es sostenible.']],example:'Un expediente puede concluir: “No firmaré hasta tener estudio de títulos, carta de aprobación con condiciones, liquidación de gastos de cierre y revisión de la promesa por un abogado”. Eso es avanzar con un criterio verificable.',concepts:['Presupuesto','Comparables','Debida diligencia','Condición de cierre','Decisión informada'],case:'Escoge un inmueble hipotético o real. Prepara una hoja resumen con presupuesto, tres alternativas comparadas, cuota y sensibilidad, verificación jurídica, fuentes oficiales consultadas y decisión razonada.',summary:'La decisión final integra presupuesto, escenarios financieros, comparables, documentos, fuentes y riesgos. Es razonable aplazar la compra si las condiciones críticas siguen sin resolver.',question:'¿Qué demuestra que estás listo para tomar una decisión informada?',options:['Encontrar una vivienda cuyo precio publicado coincide con el préstamo ofrecido.','Poder explicar tu presupuesto completo, verificación documental, riesgos, supuestos y condiciones pendientes.','Comprar para evitar que suban los precios.'],answer:1,feedback:'Una decisión informada muestra supuestos, evidencias, riesgos y límites; también puede ser decidir esperar.'}}
];
const TERMS=[
['Afectación a vivienda familiar','Jurídico','Protección que puede limitar la disposición o gravamen de una vivienda familiar, según sus requisitos y excepciones legales. Verifica su inscripción y el caso con un profesional.'],['Avalúo','Financiero','Estimación técnica del valor de un inmueble hecha bajo el alcance y método definidos por un avaluador competente. No garantiza el precio de venta.'],['Área privada','Mercado','Área de uso privado de una unidad inmobiliaria conforme a los documentos aplicables. Distingue área construida y privada antes de comparar.'],['Capacidad de pago','Financiero','Posibilidad de asumir cuotas y costos sin comprometer gastos esenciales, deudas ni una reserva razonable. La entidad también evalúa sus propios criterios.'],['Certificado de tradición y libertad','Jurídico','Documento registral que informa inscripciones y antecedentes del inmueble identificado por matrícula inmobiliaria. Solicítalo en los canales oficiales de la SNR.'],['Cuota inicial','Financiero','Recursos del comprador destinados a cubrir parte del precio que no se financia con deuda u otros recursos confirmados.'],['Estudio de títulos','Jurídico','Revisión profesional de antecedentes, títulos y documentos del inmueble para identificar riesgos y condiciones jurídicas de una operación.'],['Estrato','Mercado','Clasificación de inmuebles residenciales usada principalmente para la aplicación de esquemas tarifarios de servicios públicos. No mide calidad ni valor comercial.'],['Flujo de caja','Inversión','Entradas y salidas de dinero de una inversión durante un periodo; puede incluir canon, vacancia, gastos y cuotas de financiación.'],['Hipoteca','Jurídico','Derecho de garantía constituido sobre un inmueble para respaldar una obligación, con los efectos previstos en el contrato y la ley.'],['Leasing habitacional','Financiero','Modalidad de financiación de vivienda mediante contrato de leasing con una entidad autorizada y opción de adquisición en las condiciones pactadas. Consulta costos y contrato de cada entidad.'],['Matrícula inmobiliaria','Jurídico','Identificador único de un inmueble en el sistema de registro inmobiliario colombiano. Permite solicitar y revisar información registral.'],['Patrimonio de familia','Jurídico','Figura legal de protección de determinados inmuebles familiares, con reglas sobre constitución, límites y cancelación. Revisa el caso concreto.'],['Precio por metro cuadrado','Mercado','Precio dividido por el área de referencia. Solo compara bien cuando ubicación, características y tipo de área son similares.'],['Promesa de compraventa','Jurídico','Contrato preparatorio que establece condiciones, obligaciones y plazo para celebrar una compraventa futura. Revisa cláusulas, sanciones y condiciones antes de firmar.'],['Propiedad horizontal','Jurídico','Régimen que organiza unidades privadas, bienes comunes, administración y obligaciones dentro de un edificio o conjunto.'],['Rentabilidad bruta','Inversión','Ingreso anual teórico por arriendo dividido por el precio o costo definido. No incluye gastos, vacancia, impuestos ni financiación.'],['Rentabilidad neta','Inversión','Medida de ingresos después de los costos que se hayan incluido; especifica siempre qué gastos entraron al cálculo.'],['Separación','Adquisición','Pago o acuerdo preliminar para reservar un inmueble. Sus efectos dependen del documento: verifica devolución, destinatario, plazo y condiciones.'],['Tasa efectiva anual (EA)','Financiero','Forma de expresar una tasa de interés anual con capitalización efectiva. Compara la misma base y revisa seguros y costos asociados.'],['UVR','Financiero','Unidad de cuenta cuyo valor diario en pesos refleja las variaciones del IPC y es certificada por el Banco de la República. En un crédito expresado en UVR, el equivalente en pesos del saldo puede cambiar con el valor de la UVR; también influyen la tasa y el sistema de amortización. La UVR no es una tasa de interés.'],['VIS','Vivienda','Categoría legal de vivienda de interés social con definición y topes establecidos por la regulación vigente. Confirma reglas actuales con Minvivienda.'],['VIP','Vivienda','Categoría de vivienda de interés prioritario dentro de la política de vivienda. Los topes y condiciones aplicables requieren verificación oficial vigente.'],['Vacancia','Inversión','Periodo durante el cual un inmueble destinado al arriendo no genera canon, aunque puede seguir generando gastos.']
];
const SOURCES=[['Ministerio de Vivienda — VIS y VIP','https://minvivienda.gov.co/viceministerio-de-vivienda-vis-y-vip'],['Superintendencia Financiera — Información para personas','https://www.superfinanciera.gov.co/personas/'],['Superintendencia de Notariado y Registro — Certificado de tradición','https://www.supernotariado.gov.co/atencion-servicios-ciudadania/tramites-y-servicios/'],['Portal oficial para certificado de tradición','https://certificados.supernotariado.gov.co/'],['DANE — Índice de precios de vivienda nueva','https://www.dane.gov.co/index.php/estadisticas-por-tema/construccion/indice-de-precios-de-vivienda-nueva-ipvn/indice-de-precios-de-vivienda-nueva'],['Banco de la República — UVR y precios de vivienda','https://www.banrep.gov.co/es/estadisticas-economicas/series-historicas/precios-inflacion'],['Minvivienda — programas de vivienda','https://www.minvivienda.gov.co/viceministerio-de-vivienda'],['IGAC','https://www.igac.gov.co/'],['DIAN','https://www.dian.gov.co/'],['Superfinanciera — preguntas sobre créditos','https://www.superfinanciera.gov.co/preguntas-frecuentes/11/11-creditos/'],['Minvivienda — precios de vivienda nueva en pesos','https://www.minvivienda.gov.co/sala-de-prensa/gobierno-nacional-reitera-que-los-precios-de-la-vivienda-deben-informarse-y-definirse-en-las-promesas-de-compraventa-en-pesos-colombianos'],['SNR — alerta sobre certificados fraudulentos','https://www.supernotariado.gov.co/prensa/noticias/snr-advierte-sobre-pagina-web-que-emite-ctl-de-forma-fraudulenta/'],['SIC — derechos al comprar vivienda nueva','https://sedeelectronica.sic.gov.co/noticias/la-superintendencia-expidio-circular-externa-sobre-la-promocion-publicidad-y-comercializacion-de-proyectos-constructivos-destinados-vivienda'],['Función Pública — Ley 820 de arrendamiento urbano','https://www1.funcionpublica.gov.co/eva/gestornormativo/norma.php?i=8738'],['MinCIT — Registro Nacional de Turismo','https://www.mincit.gov.co/minturismo/analisis-sectorial-y-promocion/registro-nacional-de-turismo'],['MinCIT — Formalización turística y uso del suelo','https://www.mincit.gov.co/minturismo/analisis-sectorial-y-promocion/preguntas-frecuentes-relacionadas-con-formalizacio'],['MinCIT — Abecé de formalización turística','https://portucolombia.mincit.gov.co/getmedia/e4d79c83-b982-4482-986d-a55463a24a76/ABC-Formalizacion.pdf.aspx'],['Función Pública — Ley 2068 de 2020 (servicios turísticos)','https://www.funcionpublica.gov.co/eva/gestornormativo/norma.php?i=172558'],['Minvivienda — Informe de empalme FONVIVIENDA, 30/06/2026','https://www.minvivienda.gov.co/sites/default/files/documentos/20260630_fonvivienda_informe_empalme_0.pdf'],['Minvivienda — Circular 0005 de 2026','https://minvivienda.gov.co/normativa/circular-0005-2026']];
const STORAGE_KEY='mentor-inmobiliario-colombia-v1';
const DEFAULT_STATE={profile:null,completed:[],scores:{},attempts:{},lessonHistory:[],achievements:[],chat:[],properties:[],loans:[],activeModule:1,lastVisit:null,bookmarks:[],diagnostic:null,caseNotes:{}};
function loadState(){return structuredClone(DEFAULT_STATE)}
function readLegacyState(){try{return JSON.parse(localStorage.getItem(STORAGE_KEY)||'null')}catch{return null}}
const legacyLearningState=readLegacyState();
let state=loadState();let currentPage='inicio';let currentLesson=1;let activeTool='compra';let activeGlossaryLetter='';let toastTimer;let latestMentorResponse=null;let lastRenderedHash=null;let authMode='signin';
const $=(selector,root=document)=>root.querySelector(selector);const $$=(selector,root=document)=>[...root.querySelectorAll(selector)];
function esc(s=''){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function learningPayload(source=state){return {profile:source.profile?{name:source.profile.name,objective:source.profile.objective,horizon:source.profile.horizon,level:source.profile.level}:null,completed:source.completed||[],scores:source.scores||{},attempts:source.attempts||{},lessonHistory:source.lessonHistory||[],achievements:source.achievements||[],bookmarks:source.bookmarks||[],diagnostic:source.diagnostic||null,caseNotes:source.caseNotes||{},activeModule:source.activeModule||1,lastVisit:source.lastVisit||null}}
function persist(){if(window.MentorAuth?.user){$('.saved-state').textContent='Guardando en tu cuenta…';window.MentorAuth.queueSave(learningPayload())}}
function money(n){return new Intl.NumberFormat('es-CO',{style:'currency',currency:'COP',maximumFractionDigits:0}).format(Number.isFinite(n)?n:0)}
function number(id, fallback=0){const el=document.getElementById(id);if(!el)return fallback;const parsed=Number(String(el.value).replace(/[^\d.-]/g,''));return Number.isFinite(parsed)?parsed:fallback}
function percent(n,d){return d?100*n/d:0}
function toast(message){const el=$('#toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2700)}
function completedCount(){return state.completed.length}
function progressPct(){return Math.round(completedCount()/MODULES.length*100)}
function isUnlocked(id){return id===1||state.completed.includes(id-1)}
function nextModule(){return MODULES.find(m=>!state.completed.includes(m.id))||MODULES[9]}
function greeting(){const name=state.profile?.name;const h=new Date().getHours();const sal=h<12?'Buenos días':h<19?'Buenas tardes':'Buenas noches';return name?`${sal}, ${name}.`:`${sal}.`}
function initials(){return (state.profile?.name||'M').trim().charAt(0).toUpperCase()}
function updateShell(){const initial=initials();$('#avatar-initial').textContent=initial;$('#top-avatar').textContent=initial;$('#profile-name').textContent=state.profile?.name||'Mi perfil';const labels={diagnostico:'Diagnóstico',inicio:'Mi aprendizaje',ruta:'Ruta de aprendizaje',herramientas:'Herramientas',glosario:'Glosario',mentor:'Mi mentor',leccion:'Lección'};$('#current-section').textContent=labels[currentPage]||'Mi aprendizaje';$$('.nav-link').forEach(a=>a.classList.toggle('active',a.dataset.page===currentPage));}
function pageHeading(kicker,title,subtitle,action=''){return `<div class="page-heading"><div><p class="eyebrow">${kicker}</p><h1>${title}</h1>${subtitle?`<p>${subtitle}</p>`:''}</div>${action}</div>`}
function sourceFooter(){return `<footer class="source-footer"><strong>Fuentes oficiales para consultar.</strong> La app no comprueba automáticamente que sus enlaces o contenidos sigan vigentes. Verifica fecha, requisitos y ámbito local directamente con la entidad antes de decidir.<div>${SOURCES.slice(0,9).map(s=>`<a class="source-link" href="${s[1]}" target="_blank" rel="noopener noreferrer">${esc(s[0])}</a>`).join(' · ')}</div></footer>`}
function moduleRow(m){const done=state.completed.includes(m.id),locked=!isUnlocked(m.id),label=done?'Completado':locked?'Bloqueado':'Disponible';return `<a class="module-row ${locked?'locked':''}" href="${locked?'#ruta':`#leccion/${m.id}`}" ${locked?'aria-label="Módulo bloqueado, completa el anterior"':''}><span class="module-number">${String(m.id).padStart(2,'0')}</span><span class="module-info"><strong>${esc(m.title)}</strong><small>${m.duration} · ${label}</small></span><span class="module-state">${done?'✓':locked?'⌑':'→'}</span></a>`}
function achievementsPanel(){
 const badges=[['primer-paso','Primer paso','Terminaste tu primera lección.','⌂'],['mitad-ruta','Media ruta','Completaste cinco módulos.','✦'],['ruta-completa','Ruta completa','Terminaste los diez módulos.','🏆']];
 const perfect=state.achievements.filter(x=>x.startsWith('perfecto-')).map(x=>Number(x.split('-')[1]));
 return `<section style="margin-top:25px"><div class="section-head"><h2>Reconocimientos</h2><span class="text-link">${state.achievements.length} obtenidos</span></div><div class="achievement-list">${badges.map(([id,title,detail,icon])=>`<article class="achievement-chip ${state.achievements.includes(id)?'earned':''}"><span>${icon}</span><div><strong>${title}</strong><small>${detail}</small></div><b>${state.achievements.includes(id)?'✓':'·'}</b></article>`).join('')}${perfect.map(id=>`<article class="achievement-chip earned"><span>✧</span><div><strong>Evaluación perfecta · Módulo ${id}</strong><small>Aprobaste esta evaluación con el 100 %.</small></div><b>✓</b></article>`).join('')}</div></section>`;
}
function activityPanel(){
 const recent=[...state.lessonHistory].slice(-5).reverse();
 return `<section style="margin-top:22px"><div class="section-head"><h2>Actividad reciente</h2><span class="text-link">${state.lessonHistory.length} intentos registrados</span></div>${recent.length?`<div class="panel timeline">${recent.map(item=>`<div class="timeline-item"><span class="timeline-dot">${item.correct?'✓':'↻'}</span><div class="timeline-copy"><strong>${esc(MODULES[item.id-1]?.title||'Lección')}</strong><small>${item.correct?'Evaluación aprobada':'Repaso pendiente'} · ${new Intl.DateTimeFormat('es-CO',{dateStyle:'medium'}).format(new Date(item.at))}</small></div></div>`).join('')}</div>`:'<div class="empty-route">Al responder una evaluación aparecerán aquí la lección, el resultado y la fecha para que puedas seguir tu avance.</div>'}</section>`;
}
