function personalizedPlan(){
 const profile=state.profile||{};
 const goals={vivir:'Comprar una vivienda para vivir',invertir:'Analizar una inversión inmobiliaria',explorar:'Conocer el mercado antes de decidir'};
 const horizons={aprendiendo:'Aún estás aprendiendo',12:'Te gustaría comprar en menos de 1 año',24:'Te gustaría comprar en 1–2 años',36:'Te gustaría comprar en más de 2 años'};
 const levels={principiante:'Desde cero',intermedio:'Con algunos conocimientos',avanzado:'Con experiencia previa'};
 const focus=profile.objective==='invertir'?'Al estudiar el mercado y las finanzas, presta especial atención a los módulos 8 y 9; los simuladores te ayudan a explicitar supuestos.':'Los módulos 3, 5, 6 y 7 te ayudarán a comprobar presupuesto, ayudas vigentes, proceso y documentos.';
 return `<section class="panel" style="margin:0 0 17px;background:#f5f4ed"><p class="eyebrow">TU ENFOQUE PERSONAL</p><h3>${esc(goals[profile.objective]||goals.explorar)}</h3><p class="progress-copy" style="font-size:10px;color:var(--muted);line-height:1.7;margin:8px 0">${esc(horizons[profile.horizon]||horizons.aprendiendo)} · Nivel inicial: ${esc(levels[profile.level]||levels.principiante)}.<br>${esc(focus)}</p><a class="source-link" href="#herramientas">${profile.objective==='invertir'?'Practicar con el evaluador de inversión':'Practicar con el simulador de compra'} →</a></section>`;
}
function routePage(){const next=nextModule();return `${pageHeading('PROGRESO PASO A PASO','Tu ruta inmobiliaria','Avanza en orden: cada módulo incluye contenido práctico y una evaluación. Supera una lección para desbloquear la siguiente.' ,`<div class="backup-tools"><div class="backup-actions"><button class="button button-secondary" type="button" data-export-learning>Descargar respaldo</button><button class="button button-secondary" type="button" data-import-learning>Restaurar respaldo</button></div><p class="backup-note">El archivo incluye tu nombre, ruta, resultados y notas libres; revisa las notas antes de compartirlo. No incluye ingresos, ahorros, simuladores ni chat de IA.</p><input id="learning-backup-file" class="sr-only" type="file" accept="application/json,.json" aria-label="Seleccionar archivo de respaldo JSON"></div>`)}<section class="panel" style="margin-bottom:17px"><div class="progress-copy"><h3>Una decisión informada se construye por etapas.</h3><p>Has completado ${completedCount()} de 10 módulos (${progressPct()}%). La ruta se guarda en este dispositivo.</p></div><div class="progress-track"><div class="progress-fill" style="width:${progressPct()}%"></div></div><div class="progress-meta"><span>Próximo: ${esc(next.title)}</span><span>${progressPct()}%</span></div></section>${personalizedPlan()}<div class="module-grid">${MODULES.map(m=>{const done=state.completed.includes(m.id),locked=!isUnlocked(m.id);return `<article class="module-card ${locked?'is-locked':''}"><div class="module-top"><span class="module-icon">${m.icon}</span><span class="module-status">${done?'✓ Completado':locked?'⌑ Bloqueado':'● Disponible'}</span></div><h3>Módulo ${String(m.id).padStart(2,'0')} · ${esc(m.title)}</h3><p>${esc(m.description)}</p><div class="module-card-foot"><small>${m.duration} · ${done?(state.scores[m.id]??0)+'%':'1 evaluación'}</small>${locked?'<span class="locked-message">Completa el anterior</span>':`<button data-open-lesson="${m.id}">${done?'Repasar':'Estudiar'} →</button>`}</div></article>`}).join('')}</div>${sourceFooter()}`}
function lessonPage(id){const m=MODULES.find(x=>x.id===id);if(!m)return routePage();if(!isUnlocked(id)){currentPage='ruta';return routePage()}currentLesson=id;const l=m.lesson;const extra=LESSON_EXTRAS[id];const notice=id===5?`<aside class="callout current-program-notice"><strong>Actualización de subsidios consultada: 20 de noviembre de 2026</strong><p>El informe de empalme de Minvivienda reporta que las nuevas postulaciones a Mi Casa Ya están suspendidas desde el 20 de diciembre de 2024. La Circular 0005 de 2026 fijó el 15 de octubre de 2026 como cierre para cargar documentos de hogares con cupos VIP preasignados para esa vigencia. Esto describe ese programa y ese proceso; no significa que todos los demás subsidios estén cerrados. Comprueba las convocatorias y requisitos vigentes directamente con el operador antes de contar una ayuda en tu presupuesto.</p><a href="${SOURCES[18][1]}" target="_blank" rel="noopener noreferrer">Informe de empalme de FONVIVIENDA ↗</a> · <a href="${SOURCES[19][1]}" target="_blank" rel="noopener noreferrer">Circular 0005 de 2026 ↗</a></aside>`:'';const sections=[...l.sections,...extra.sections];const questions=[{prompt:l.question,options:l.options,answer:l.answer,feedback:l.feedback},...extra.questions];const priorAnswers=Array.isArray(state.attempts[id]?.answers)?state.attempts[id].answers:[state.attempts[id]?.answer];const blocks=sections.map(([title,text],i)=>`<section class="lesson-block" id="section-${i}"><h2>${esc(title)}</h2><p>${esc(text)}</p></section>`).join('');const attempt=state.attempts[id];const failedQuestion=attempt?.answers?questions.find((q,i)=>attempt.answers[i]!==q.answer):null;const feedback=attempt?`<div class="quiz-feedback ${attempt.correct?'correct':'incorrect'}">${attempt.correct?'¡Evaluación aprobada! ':'Repasa el tema y vuelve a intentarlo. '}${attempt.correctCount===undefined?'Tu progreso anterior se conserva; responde las dos preguntas para actualizar la evaluación. ':`${attempt.correctCount}/2 correctas. `}${esc(failedQuestion?.feedback||l.feedback)}<br>Intentos en este módulo: ${attempt.count} · Mejor resultado: ${state.scores[id]??0}%</div>`:'';return `${pageHeading('MÓDULO '+String(id).padStart(2,'0')+' · '+m.title.toUpperCase(),l.title,'Una idea a la vez. Lee el ejemplo y prueba lo aprendido en el caso práctico.')}${notice}<div class="lesson-layout"><article class="lesson-card"><div class="lesson-kicker"><span>${m.icon}</span> MÓDULO ${String(id).padStart(2,'0')} <span>·</span> UNIDAD 1 DE 1 <button class="bookmark-button" data-bookmark="${id}" aria-pressed="${(state.bookmarks||[]).includes(id)}">${(state.bookmarks||[]).includes(id)?'★ Guardada':'☆ Guardar para repasar'}</button></div><p class="lesson-lead">${esc(l.lead)}</p>${lessonVisual(extra.visual)}${blocks}<section class="lesson-outcomes"><h2>Al terminar podrás</h2><ul>${extra.outcomes.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></section><div class="callout"><strong>Ejemplo en Colombia</strong><br>${esc(l.example)}</div><section class="lesson-block"><h2>✦ Caso práctico</h2><p>${esc(l.case)}</p><textarea id="case-answer" class="field" aria-label="Tu respuesta al caso práctico" placeholder="Escribe tus observaciones o ideas aquí…" style="width:100%;min-height:112px;border:1px solid var(--line);padding:13px;border-radius:8px;font:12px/1.65 var(--sans)">${esc(state.caseNotes?.[id]||'')}</textarea><button class="button button-outline button-small" style="margin-top:8px" data-save-case="${id}">Guardar mis notas</button></section><section class="lesson-block" id="lesson-quiz"><h2>Comprueba lo aprendido</h2><p>Responde las dos preguntas para cerrar esta lección. Puedes intentarlo de nuevo.</p><form id="quiz-form" data-module="${id}">${questions.map((q,qi)=>`<fieldset class="quiz-question"><legend><span>Pregunta ${qi+1} de 2</span>${esc(q.prompt)}</legend>${q.options.map((o,oi)=>`<label class="quiz-option"><input type="radio" name="answer-${qi}" value="${oi}" ${priorAnswers[qi]===oi?'checked':''}><span>${esc(o)}</span></label>`).join('')}</fieldset>`).join('')}<button type="submit" class="button button-primary button-small">Comprobar respuestas</button></form>${feedback}</section><section class="lesson-block"><h2>Resumen de la lección</h2><p>${esc(l.summary||l.lead)} ${sections.map(s=>esc(s[0])).join(' · ')}. Comprueba siempre las condiciones concretas de tu caso.</p></section><div class="lesson-actions"><button class="button button-outline button-small" data-page-link="ruta">← Todos los módulos</button>${id<10?`<button class="button button-primary button-small" data-next-lesson="${id+1}" ${!state.completed.includes(id)?'disabled title="Primero aprueba la evaluación"':''}>Siguiente módulo →</button>`:'<button class="button button-primary button-small" data-page-link="herramientas">Ir a los simuladores →</button>'}</div></article><aside class="lesson-sidebar"><section class="panel lesson-side-panel"><h3>EN ESTA LECCIÓN</h3>${sections.map((s,i)=>`<a class="source-link" style="display:block;font-size:9px;margin:9px 0;text-decoration:none" href="#section-${i}">${i+1}. ${esc(s[0])}</a>`).join('')}<a class="source-link" style="display:block;font-size:9px;margin:9px 0;text-decoration:none" href="#lesson-quiz">Evaluación</a></section><section class="panel lesson-side-panel"><h3>CONCEPTOS CLAVE</h3>${l.concepts.map(c=>`<span class="concept-pill">${esc(c)}</span>`).join('')}</section><section class="panel lesson-side-panel"><h3>TU PROGRESO</h3><div class="progress-track"><div class="progress-fill" style="width:${state.completed.includes(id)?100:state.attempts[id]?.correct?100:0}%"></div></div><div class="progress-meta"><span>${state.completed.includes(id)?'Completado':state.attempts[id]?.correct?'Evaluación aprobada':'Pendiente'}</span><span>${state.scores[id]??0}%</span></div></section>${id===5?`<section class="panel lesson-side-panel"><h3>FUENTE OFICIAL</h3><a class="source-link" href="${SOURCES[6][1]}" target="_blank" rel="noopener noreferrer">Revisar programas de vivienda →</a><p class="tool-disclaimer">Confirma cierres, disponibilidad y requisitos en el canal oficial.</p></section>`:''}</aside></div>${sourceFooter()}`}
function toolsPage(){const tabs=[['compra','Compra de vivienda'],['creditos','Compara créditos'],['propiedades','Compara propiedades'],['inversion','Evalúa inversión']];return `${pageHeading('PRACTICA CON TUS NÚMEROS','Herramientas de decisión','Explora escenarios con tus propios supuestos. Las estimaciones no son ofertas bancarias, avalúos ni asesoría financiera.')}<div class="tool-tabs" role="tablist">${tabs.map(([id,name])=>`<button class="tool-tab ${activeTool===id?'active':''}" role="tab" aria-selected="${activeTool===id}" data-tool="${id}">${name}</button>`).join('')}</div>${toolQuickGuide(activeTool)}<div id="tool-content">${renderActiveTool()}</div>${sourceFooter()}`}
function field(id,label,val,placeholder='',hint='',type='number',step='any'){return `<div class="field"><label for="${id}">${label}</label><input id="${id}" type="${type}" ${type==='number'?`min="0" step="${step}"`:''} value="${val??''}" placeholder="${placeholder}">${hint?`<small class="field-hint">${hint}</small>`:''}</div>`}
function result(id,content){$('#'+id)?.remove();const target=$('[data-result-host]');if(target)target.insertAdjacentHTML('beforeend',`<div class="result-card" id="${id}">${content}</div>`)}
function renderActiveTool(){if(activeTool==='compra')return `<section class="tool-grid"><article class="tool-card"><h2>Simulador de compra</h2><p>Calcula una cuota aproximada y revisa cuánto te faltaría para la cuota inicial.</p><div class="field-grid">${field('buy-price','Precio del inmueble (COP)','280000000')}${field('buy-savings','Ahorros destinados a la compra (COP)',state.profile?.savings??'60000000')}${field('buy-income','Ingresos mensuales del hogar (COP)',state.profile?.income??'8000000')}${field('buy-expenses','Gastos mensuales y otras deudas (COP)','3200000')}${field('buy-down','Cuota inicial (COP)','56000000')}${field('buy-term','Plazo (años)','20','','Entre 1 y 40','number','1')}${field('buy-rate','Tasa efectiva anual (%)','12.5','','Supuesto editable; confirma la oferta','number','0.01')}${field('buy-cost-rate','Otros costos iniciales estimados (%)','3','','Supuesto editable; cotiza por separado','number','0.1')}</div><div class="form-actions"><button class="button button-primary button-small" data-calculate="buy">Calcular escenario →</button></div><div data-result-host></div><p class="tool-disclaimer">Cuota estimada con amortización en pesos y tasa EA convertida a tasa mensual equivalente. No incluye seguros, administración ni variación UVR. El 3% es un supuesto editable, no una tarifa oficial.</p></article><article class="tool-card"><h2>¿Qué incluye tu presupuesto?</h2><p>Usa esto como lista de revisión al solicitar cotizaciones de cierre.</p><div class="timeline"><div class="timeline-item"><span class="timeline-dot">1</span><div class="timeline-copy"><strong>Precio y financiación</strong><small>Oferta, cuota inicial, desembolso y condiciones del crédito.</small></div></div><div class="timeline-item"><span class="timeline-dot">2</span><div class="timeline-copy"><strong>Trámites y documentos</strong><small>Escritura, registro, avalúo y estudio de títulos. Pide liquidaciones de cada entidad.</small></div></div><div class="timeline-item"><span class="timeline-dot">3</span><div class="timeline-copy"><strong>Costos recurrentes</strong><small>Administración, seguros, impuestos, servicios y mantenimiento.</small></div></div><div class="timeline-item"><span class="timeline-dot">4</span><div class="timeline-copy"><strong>Fondo de respaldo</strong><small>Conserva dinero disponible para mudanza, reparaciones e imprevistos.</small></div></div></div></article></section>`;
 if(activeTool==='creditos')return `<section class="tool-grid"><article class="tool-card"><h2>Comparador de financiación</h2><p>Registra ofertas recibidas y compara cuotas estimadas en la misma moneda y con los mismos supuestos.</p><div class="field-grid">${field('loan-name','Entidad o escenario','Banco A','Nombre corto','','text')}${field('loan-amount','Monto a financiar (COP)','220000000')}${field('loan-term','Plazo (años)','20','','','number','1')}${field('loan-rate','Tasa EA (%)','12.5','','Compara la misma modalidad','number','0.01')}</div><div class="form-actions"><button class="button button-primary button-small" data-calculate="add-loan">Agregar escenario +</button></div><div id="loans-table">${loanTable()}</div><p class="tool-disclaimer">Compara también seguros, tasa fija o UVR, comisiones, condiciones de prepago y costo total. La cuota no es una oferta ni una aprobación.</p></article><article class="tool-card"><h2>Qué preguntar a cada entidad</h2><div class="timeline"><div class="timeline-item"><span class="timeline-dot">?</span><div class="timeline-copy"><strong>¿La tasa está expresada en EA y en qué modalidad?</strong></div></div><div class="timeline-item"><span class="timeline-dot">?</span><div class="timeline-copy"><strong>¿Cuál es la cuota con seguros y cómo puede cambiar?</strong></div></div><div class="timeline-item"><span class="timeline-dot">?</span><div class="timeline-copy"><strong>¿Cuáles son los costos de estudio, avalúo y desembolso?</strong></div></div><div class="timeline-item"><span class="timeline-dot">?</span><div class="timeline-copy"><strong>¿Cómo se aplican abonos y qué condiciones tiene el prepago?</strong></div></div></div><p class="tool-disclaimer">Fuentes y tasas de mercado cambian. Solicita la oferta escrita directamente a la entidad y consulta fuentes de la Superintendencia Financiera y del Banco de la República.</p></article></section>`;
 if(activeTool==='propiedades')return `<section class="tool-grid"><article class="tool-card"><h2>Comparador de propiedades</h2><p>Registra inmuebles y compáralos con la misma base de área. Tus registros quedan en este dispositivo.</p><div class="field-grid">${field('prop-name','Nombre o proyecto','Opción A','Nombre','','text')}${field('prop-location','Ciudad y sector','Bogotá · sector','','','text')}${field('prop-features','Características relevantes','2 habitaciones, parqueadero…','','Habitaciones, parqueadero, balcón, antigüedad…','text')}${field('prop-price','Precio (COP)','280000000')}${field('prop-area','Área (m²)','62','','Área privada o construida','number','0.1')}${field('prop-admin','Administración mensual (COP)','0')}${field('prop-type','Estado','Usada','Nueva, usada, sobre planos…','','text')}</div><div class="form-actions"><button class="button button-primary button-small" data-calculate="add-property">Agregar propiedad +</button></div><div id="properties-table">${propertyTable()}</div><p class="tool-disclaimer">Precio/m² es una referencia. Compara el mismo tipo de área y propiedades semejantes; confirma estado, servicios, gravámenes y costos.</p></article><article class="tool-card"><h2>Qué comparar en una visita</h2><div class="timeline"><div class="timeline-item"><span class="timeline-dot">✓</span><div class="timeline-copy"><strong>Ubicación y transporte</strong><small>Visita en distintos horarios y valida rutas.</small></div></div><div class="timeline-item"><span class="timeline-dot">✓</span><div class="timeline-copy"><strong>Estado físico</strong><small>Revisa humedades, instalaciones, ruido y acabados.</small></div></div><div class="timeline-item"><span class="timeline-dot">✓</span><div class="timeline-copy"><strong>Costos y reglamento</strong><small>Pide administración, actas y normas de propiedad horizontal.</small></div></div><div class="timeline-item"><span class="timeline-dot">✓</span><div class="timeline-copy"><strong>Situación jurídica</strong><small>Solicita matrícula, tradición y estudio profesional.</small></div></div></div></article></section>`;
 return `<section class="tool-grid"><article class="tool-card"><h2>Evaluador de inversión</h2><p>Estima rentabilidad bruta y neta operativa, ingreso por arriendo, flujo de caja y ROI simple de efectivo con tus supuestos.</p><div class="field-grid">${field('inv-price','Precio total de compra (COP)','300000000')}${field('inv-rent','Canon mensual esperado (COP)','2200000')}${field('inv-vacancy','Meses vacíos al año','1','','Supuesto (0–12)','number','1')}${field('inv-costs','Gastos operativos mensuales (COP)','350000')}${field('inv-mortgage','Cuota mensual de deuda (COP)','0')}${field('inv-initial','Capital propio invertido (COP)','90000000')}</div><div class="form-actions"><button class="button button-primary button-small" data-calculate="investment">Calcular rentabilidad →</button></div><div data-result-host></div><p class="tool-disclaimer">Estimación simplificada antes de impuestos. La “rentabilidad neta operativa” resta solo los gastos mensuales indicados y no incorpora costos de adquisición, reparaciones extraordinarias ni cambios de valor.</p></article><article class="tool-card"><h2>Prueba el escenario desfavorable</h2><p>Un análisis útil incluye meses sin canon, reparaciones no previstas y gastos recurrentes.</p><div class="callout">La tasa de ocupación, el canon, impuestos, reglas de arrendamiento y el precio de reventa no se predicen con certeza. Documenta cada supuesto y consulta a un profesional para tu caso.</div><a class="source-link" href="#glosario">Repasar: vacancia, flujo de caja y rentabilidad →</a></article></section>`}
const payment=MentorCore.monthlyPayment;
function calcBuy(){const price=number('buy-price'),saving=number('buy-savings'),income=number('buy-income'),expenses=number('buy-expenses'),down=number('buy-down'),years=number('buy-term'),rate=number('buy-rate'),costRate=number('buy-cost-rate');if(price<=0||years<=0||down>price||[saving,income,expenses,down,rate,costRate].some(x=>x<0)){toast('Revisa precios, valores no negativos y plazo.');return}const scenario=MentorCore.homePurchaseScenario({price,savings:saving,income,expenses,downPayment:down,termYears:years,annualRatePercent:rate,closingCostPercent:costRate});const {principal,installment:monthly,closingCosts:costs,paymentAndExpensesToIncomePercent:ratio,savingsGap:gap}=scenario;let html=`<p class="result-title">ESCENARIO APROXIMADO · CUOTA FIJA EN PESOS</p><div class="result-number">${money(monthly)} <span style="font:400 9px var(--sans);color:#7b897f">/ mes estimado</span></div><div class="result-grid"><div class="result-item"><small>Monto a financiar</small><strong>${money(principal)}</strong></div><div class="result-item"><small>Otros costos (supuesto ${costRate}%)</small><strong>${money(costs)}</strong></div><div class="result-item"><small>Faltante vs. ahorros actuales*</small><strong>${money(gap)}</strong></div><div class="result-item"><small>Cuota + otros gastos / ingresos</small><strong>${ratio!==null?ratio.toFixed(1)+'%':'—'}</strong></div></div><p class="result-caption">*El cálculo suma cuota inicial y costos supuestos frente a tus ahorros. El porcentaje orienta el análisis, no es un umbral universal. La entidad decide aprobación y condiciones.</p>`;result('buy-result',html)}
function getMonthly(elId){const e=document.getElementById(elId);return e?Number(e.value):0}
function addLoan(){const name=$('#loan-name').value.trim()||`Escenario ${state.loans.length+1}`,amount=number('loan-amount'),years=number('loan-term'),rate=number('loan-rate');if(amount<=0||years<=0||rate<0){toast('Ingresa monto, tasa y plazo válidos.');return}state.loans.push({id:Date.now(),name,amount,years,rate,monthly:payment(amount,rate,years)});persist();$('#loans-table').innerHTML=loanTable();toast('Escenario agregado.')}
function loanTable(){if(!state.loans.length)return '<div class="empty-state">Aún no has agregado ofertas. Registra al menos dos para compararlas.</div>';return `<div class="table-wrap"><table class="data-table"><thead><tr><th>Escenario</th><th>Capital</th><th>Tasa EA</th><th>Plazo</th><th>Cuota estimada</th><th>Total pagado</th><th>Interés aprox.</th><th></th></tr></thead><tbody>${state.loans.map((x,i)=>`<tr><td>${esc(x.name)}</td><td>${money(x.amount)}</td><td>${x.rate}%</td><td>${x.years} años</td><td>${money(x.monthly)}</td><td>${money(x.monthly*x.years*12)}</td><td>${money(Math.max(0,x.monthly*x.years*12-x.amount))}</td><td><button class="table-remove" data-remove-loan="${x.id}" aria-label="Eliminar escenario">×</button></td></tr>`).join('')}</tbody></table></div>`}
function addProperty(){const name=$('#prop-name').value.trim()||`Opción ${state.properties.length+1}`,area=number('prop-area'),price=number('prop-price');if(area<=0||price<=0){toast('Ingresa precio y área válidos.');return}state.properties.push({id:Date.now(),name,location:$('#prop-location').value.trim(),features:$('#prop-features').value.trim(),price,area,admin:number('prop-admin'),type:$('#prop-type').value.trim()});persist();$('#properties-table').innerHTML=propertyTable();toast('Propiedad agregada.')}
function propertyTable(){if(!state.properties.length)return '<div class="empty-state">Agrega propiedades para ver una comparación en la misma tabla.</div>';return `${propertyComparisonVisual()}<div class="table-wrap"><table class="data-table"><thead><tr><th>Propiedad / ubicación</th><th>Precio</th><th>Área</th><th>Precio / m²</th><th>Admón. / mes</th><th></th></tr></thead><tbody>${state.properties.map(x=>`<tr><td><strong>${esc(x.name)}</strong><br>${esc(x.location)} · ${esc(x.type)}<br>${esc(x.features||'')}</td><td>${money(x.price)}</td><td>${x.area} m²</td><td>${money(MentorCore.pricePerArea(x.price,x.area))}</td><td>${money(x.admin)}</td><td><button class="table-remove" data-remove-property="${x.id}" aria-label="Eliminar propiedad">×</button></td></tr>`).join('')}</tbody></table></div>`}
function calcInvestment(){const price=number('inv-price'),rent=number('inv-rent'),vacancy=Math.min(12,number('inv-vacancy')),costs=number('inv-costs'),debt=number('inv-mortgage'),capital=number('inv-initial');if(price<=0||[rent,vacancy,costs,debt,capital].some(x=>x<0)){toast('Revisa precios y valores no negativos.');return}const scenario=MentorCore.investmentScenario({price,monthlyRent:rent,vacantMonths:vacancy,monthlyOperatingCosts:costs,monthlyDebtPayment:debt,investedCapital:capital});const {annualGrossIncome:grossAnnual,grossYieldPercent:grossYield,operatingNetIncome:netAnnual,operatingNetYieldPercent:netYield,annualCashFlow:cash,cashOnEquityPercent:equityReturn}=scenario;result('investment-result',`<p class="result-title">INDICADORES ESTIMADOS · ANTES DE IMPUESTOS</p><div class="result-grid"><div class="result-item"><small>Rentabilidad bruta anual / precio</small><strong>${grossYield.toFixed(2)}%</strong></div><div class="result-item"><small>Rentabilidad neta operativa estimada / precio</small><strong>${netYield.toFixed(2)}%</strong></div><div class="result-item"><small>Ingreso anual tras vacancia</small><strong>${money(grossAnnual)}</strong></div><div class="result-item"><small>Neto operativo estimado (antes de deuda)</small><strong>${money(netAnnual)}</strong></div><div class="result-item"><small>Flujo anual tras deuda</small><strong>${money(cash)}</strong></div></div>${equityReturn!==null?`<p class="result-caption">ROI simple del flujo anual / capital propio: ${equityReturn.toFixed(2)}%. No incluye valorización, impuestos ni todos los costos; no es una rentabilidad garantizada.</p>`:''}`)}
function glossaryPage(){const letters=[...'ABCDEFGHIJKLMNOPQRSTUVWXYZ'];let list=TERMS.filter(t=>(!activeGlossaryLetter||t[0].toLocaleUpperCase('es').startsWith(activeGlossaryLetter))&&t[0].toLowerCase().includes(($('#glossary-search')?.value||'').toLocaleLowerCase('es')));return `${pageHeading('DICCIONARIO PARA EMPEZAR','Glosario inmobiliario','Términos financieros, jurídicos y de vivienda colombianos, explicados con lenguaje sencillo.')}<div class="glossary-toolbar"><div class="search-box"><span>⌕</span><input type="search" id="glossary-search" placeholder="Busca un término…" aria-label="Buscar en el glosario" value="${esc($('#glossary-search')?.value||'')}"></div></div><div class="letter-filter">${['Todos',...letters].map(ch=>`<button class="${(ch==='Todos'&&!activeGlossaryLetter)||(ch===activeGlossaryLetter)?'active':''}" data-letter="${ch==='Todos'?'':ch}">${ch}</button>`).join('')}</div><div class="glossary-grid" id="glossary-entries">${glossaryCards(list)}</div>${sourceFooter()}`}
function glossaryCards(list){return list.length?list.map(([term,cat,def])=>`<article class="glossary-card"><span class="glossary-category">${esc(cat)}</span><h3>${esc(term)}</h3><p>${esc(def)}</p></article>`).join(''):'<div class="empty-state">No encontramos ese término. Prueba otra búsqueda.</div>'}
function formatMentorCheckedAt(value){const date=new Date(value);return Number.isNaN(date.getTime())?'':new Intl.DateTimeFormat('es-CO',{dateStyle:'medium',timeStyle:'short'}).format(date)}
function mentorPage(){const messages=state.chat.length?state.chat:[{role:'mentor',mode:'local',text:'Soy tu asistente inmobiliario para Colombia. Te hablaré claro: si tu plan tiene un hueco o un riesgo, te lo señalaré y te explicaré por qué. Separaré hechos, supuestos y opinión; cuando no tenga información suficiente o una regla pueda haber cambiado, lo diré y te daré fuentes oficiales. Por defecto uso reglas locales; puedes activar la IA para una pregunta concreta. Ningún asistente puede garantizar una decisión perfecta. No compartas cédulas, matrículas, claves ni documentos personales aquí.'}];return `${pageHeading('CRITERIO · EVIDENCIA · DECISIÓN','Mi mentor inmobiliario','Un asistente educativo que cuestiona supuestos, identifica riesgos y propone próximos pasos.')}${mentorKeySetup()}${mentorCaseAnalyzer()}<div class="mentor-layout"><section class="mentor-chat"><header class="chat-head"><span class="mentor-avatar">✳</span><span><strong>Mi mentor · Colombia</strong><small>Orientación local; IA opcional por consulta; no se activa automáticamente</small></span><span class="chat-status">MODO CRÍTICO</span></header><div class="mentor-principles"><strong>No te daré la razón por cortesía.</strong> Distinguiré hechos de estimaciones; si faltan datos o hace falta un profesional, lo diré de frente.</div><div class="chat-messages" id="chat-messages" aria-live="polite">${messages.map(m=>`<div class="chat-message ${m.role==='user'?'user':''}">${m.role==='mentor'&&m.mode?`<span class="mentor-origin">${m.mode==='notice'?'Aviso de búsqueda':m.mode==='ia'?(m.links?.length?'Respuesta de IA · con fuentes web':'Respuesta de IA · sin fuentes web'):'Respuesta del motor local'}</span>${m.checkedAt&&formatMentorCheckedAt(m.checkedAt)?`<small class=\"mentor-check-date\">IA consultada: ${esc(formatMentorCheckedAt(m.checkedAt))} (hora local)</small>`:''}`:''}${esc(m.text).replace(/\n/g,'<br>')}${m.sources?.length?`<div class="mentor-citations"><strong>Fuentes para comprobar</strong>${m.sources.map(i=>`<a href="${SOURCES[i][1]}" target="_blank" rel="noopener noreferrer">${esc(SOURCES[i][0])} ↗</a>`).join('')}</div>`:''}${m.links?.length?`<div class="mentor-citations"><strong>Fuentes web citadas (verifica fuente y vigencia)</strong>${m.links.map(link=>/^https:\/\//.test(link.url)?`<a href="${esc(link.url)}" target="_blank" rel="noopener noreferrer">${esc(link.title)}${link.official||/\/\/(?:[a-z0-9-]+\.)*gov\.co(?:[/:?#]|$)/i.test(link.url)?' · Oficial .gov.co':''} ↗</a>`:'').join('')}</div>`:''}${m.actions?.length?`<div class="mentor-actions">${m.actions.map(a=>`<a href="${a.href}">${esc(a.label)} →</a>`).join('')}</div>`:''}</div>`).join('')}</div><form class="chat-composer" id="mentor-form"><textarea id="mentor-input" placeholder="Cuéntame qué decisión enfrentas. Puedes omitir tus cifras personales." aria-label="Pregunta para el mentor" required></textarea><label class="mentor-ai-optin"><input id="mentor-ai-optin" type="checkbox" disabled><span><strong>Usar IA con Gemini para esta consulta</strong><small id="mentor-ai-status" role="status">Comprobando si el servidor tiene una clave de IA…</small><small>Al activarla, envía esta pregunta y hasta 4 mensajes previos a Gemini; no envía los campos del perfil ni los datos del simulador. El nivel gratuito tiene cuotas y Google puede usar el contenido para mejorar sus productos. No envíes datos privados. La búsqueda web es opcional y se activa en una casilla separada; las respuestas pueden equivocarse. <a href="https://ai.google.dev/gemini-api/terms" target="_blank" rel="noopener noreferrer">Ver términos de Gemini ↗</a></small></span></label><label class="mentor-ai-optin mentor-search-optin"><input id="mentor-web-search" type="checkbox" disabled><span><strong>Buscar en la web con Google para esta consulta</strong><small id="mentor-web-status" role="status">Disponible al conectar Gemini.</small><small>Gemini 3.x no ofrece Google Search en el nivel Free de la API. En el nivel con facturación se incluyen 5.000 solicitudes de búsqueda al mes entre Gemini 3 y modelos posteriores; luego cuestan US$14 por cada 1.000 búsquedas. Google limita por defecto a 1.500 solicitudes diarias por proyecto. Una consulta puede generar varias búsquedas y cada búsqueda puede contar por separado. La casilla está apagada por defecto. <a href="https://ai.google.dev/gemini-api/docs/pricing" target="_blank" rel="noopener noreferrer">Consultar precios vigentes ↗</a></small></span></label><button class="button button-primary button-small" type="submit">Consultar ↑</button></form><p class="mentor-privacy">No uses este chat para enviar identificaciones, claves, números de cuenta o documentos privados. En modo IA se envían la pregunta y hasta cuatro mensajes previos para dar contexto; no se envían los campos del perfil ni lo escrito en el simulador; los mensajes previos pueden mencionar datos o preferencias que hayas compartido. Puedes plantear el caso con cifras aproximadas o ficticias. Un filtro intenta detectar algunos identificadores y evitar enviarlos a la IA, pero puede no detectar todo; revisa el texto antes de enviar.</p></section><aside class="mentor-side"><section class="panel lesson-side-panel"><h3>ELIGE UN TEMA</h3>${[['¿Me conviene comprar esta vivienda usada?','compra'],['¿Cómo sé si una cuota me queda grande?','cuota'],['¿Qué riesgos tiene esta inversión para arriendo?','inversión'],['¿Qué verifico antes de separar o consignar?','anticipo'],['¿Cómo comparo dos créditos hipotecarios?','crédito'],['¿Qué puedo confirmar sobre un subsidio?','subsidio'],['Explícame qué es la UVR','uvr'],['Explícame la cuota inicial','inicial'],['¿Qué podría estar pasando por alto antes de comprar?','supuestos'],['Ponme a prueba con el siguiente módulo','repaso']].map(([q,id])=>`<button class="suggestion-button" data-suggestion="${esc(q)}">${esc(q)} →</button>`).join('')}</section><section class="panel lesson-side-panel"><h3>ASÍ RAZONA</h3><ol class="mentor-method"><li><strong>Mi lectura franca:</strong> qué parece sensato o riesgoso.</li><li><strong>Qué sabemos:</strong> hechos, cálculos y datos que faltan.</li><li><strong>Qué haría:</strong> pasos concretos antes de comprometer dinero.</li><li><strong>Cuándo escalar:</strong> banco, abogado, avaluador o entidad oficial.</li></ol></section><section class="panel lesson-side-panel"><h3>FUENTES OFICIALES</h3><ul class="sources-list">${[9,10,2,0,6,12,13].map(i=>`<li><a class="source-link" href="${SOURCES[i][1]}" target="_blank" rel="noopener noreferrer">${esc(SOURCES[i][0])} ↗</a></li>`).join('')}</ul><p class="tool-disclaimer">Normas, tasas, programas, topes y convocatorias pueden cambiar. Revisa la fuente y fecha aplicable antes de decidir.</p><button class="text-link mentor-clear" data-clear-chat>Limpiar conversación</button></section></aside></div>${sourceFooter()}`}
function mentorKeySetup(){return `<details class="mentor-key-setup panel" id="mentor-key-setup"><summary>Configura Gemini para usar el mentor con IA</summary><p>La llave se valida con Google y se conserva solo en la memoria del servidor de este computador mientras esté abierto. No se guarda en el navegador ni en archivos.</p><form id="mentor-key-form"><label for="mentor-api-key">Llave API de Gemini</label><div class="mentor-key-row"><input id="mentor-api-key" name="apiKey" type="password" autocomplete="new-password" spellcheck="false" placeholder="Pega aquí tu llave" required><button class="button button-primary button-small" type="submit">Validar y conectar</button></div><small id="mentor-key-status" role="status">Se enviará a Google solo para verificar que la llave y el modelo estén disponibles.</small></form></details>`}
async function configureMentorKey(form){const input=$('#mentor-api-key');const status=$('#mentor-key-status');const button=form.querySelector('button[type="submit"]');const apiKey=input.value;const localHost=['localhost','127.0.0.1'].includes(location.hostname);if(!localHost){status.textContent='Para habilitar Gemini en el sitio publicado, añade GEMINI_API_KEY en Vercel > Settings > Environment Variables y vuelve a desplegar. La llave no se envió.';input.value='';return}button.disabled=true;button.textContent='Validando…';status.textContent='Validando la llave con Gemini…';try{const response=await fetch('/api/configure',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({apiKey})});const payload=await response.json();if(!response.ok)throw new Error(payload.error||'No pude validar la llave.');status.textContent='Gemini quedó conectado. La llave permanece solo en la memoria del servidor local.';$('#mentor-ai-optin').disabled=false;$('#mentor-web-search').disabled=false;$('#mentor-web-status').textContent='Google Search está disponible; solo se usa si activas esta casilla.';$('#mentor-ai-status').textContent='Gemini está listo; activa la casilla para usar IA en una consulta.';$('#mentor-key-setup').open=false;toast('Gemini conectado.');}catch(error){status.textContent=error.message;}finally{input.value='';button.disabled=false;button.textContent='Validar y conectar';}}
function mentorCaseAnalyzer(){const f=(id,label,placeholder,hint='')=>`<div class="field"><label for="${id}">${label}</label><input id="${id}" type="number" ${id==='mentor-term'?'min="1" max="40" step="1"':'min="0" step="any"'} placeholder="${placeholder}" inputmode="decimal"><small class="field-hint">${hint}</small></div>`;return `<details class="mentor-analysis panel"><summary>Analiza números de una compra o inversión</summary><p class="mentor-analysis-note">El cálculo usa los supuestos que escribas solo en esta página; no se guardan ni se envían. Usa cifras aproximadas si prefieres.</p><form id="mentor-case-form"><label class="field-label" for="mentor-analysis-type">Quiero revisar</label><select id="mentor-analysis-type"><option value="compra">Compra para vivir</option><option value="inversion">Inversión para arrendar</option></select><div class="mentor-case-fields" data-case-fields="compra">${f('mentor-price','Precio del inmueble (COP)','Ej. 300000000')}${f('mentor-savings','Ahorros disponibles (COP)','Ej. 80000000','Anota lo que tendrías disponible al cierre.')}${f('mentor-income','Ingresos netos mensuales (COP)','Ej. 8000000')}${f('mentor-expenses','Gastos y deudas mensuales actuales (COP)','Ej. 3500000','Sin la cuota nueva ni los costos nuevos de vivienda.')}${f('mentor-down','Cuota inicial (COP)','Ej. 60000000')}${f('mentor-term','Plazo (años)','20')}${f('mentor-rate','Tasa efectiva anual (%)','12.5','Supuesto: pesos y tasa EA constante.')}${f('mentor-closing','Costos de compra estimados (%)','3','Supuesto editable; cotiza el valor real.')}</div><div class="mentor-case-fields hidden" data-case-fields="inversion">${f('mentor-invest-price','Precio del inmueble (COP)','Ej. 300000000')}${f('mentor-rent','Canon mensual esperado (COP)','Ej. 2200000','Usa comparables de la zona, no solo la oferta del vendedor.')}${f('mentor-vacancy','Meses vacíos estimados al año','1','Rango permitido: 0 a 12.')}${f('mentor-costs','Costos operativos mensuales (COP)','Ej. 450000','Incluye administración, seguros, impuestos y mantenimiento prorrateados.')}${f('mentor-debt','Cuota mensual de financiación (COP)','Ej. 1200000')}${f('mentor-capital','Capital propio invertido (COP)','Ej. 100000000')}</div><button class="button button-primary button-small" type="submit">Revisar el escenario →</button></form><div id="mentor-analysis-result" aria-live="polite"></div></details>`}
function submitMentorScenario(form){
 const fields=$('#mentor-analysis-type').value==='compra'
  ?[['mentor-price','price'],['mentor-savings','savings'],['mentor-income','income'],['mentor-expenses','expenses'],['mentor-down','downPayment'],['mentor-term','termYears'],['mentor-rate','annualRatePercent'],['mentor-closing','closingCostPercent']]
  :[['mentor-invest-price','price'],['mentor-rent','monthlyRent'],['mentor-vacancy','vacantMonths'],['mentor-costs','monthlyOperatingCosts'],['mentor-debt','monthlyDebtPayment'],['mentor-capital','investedCapital']];
 const input=Object.fromEntries(fields.map(([id,key])=>[key,document.getElementById(id).value]));
 const box=$('#mentor-analysis-result');
 try{const result=MentorAssistant.analyzeScenario($('#mentor-analysis-type').value,input);box.innerHTML=`<article class="mentor-case-result"><div>${esc(result.text).replace(/\n/g,'<br>')}</div>${result.sources?.length?`<div class="mentor-citations"><strong>Fuentes para contrastar</strong>${result.sources.map(i=>`<a href="${SOURCES[i][1]}" target="_blank" rel="noopener noreferrer">${esc(SOURCES[i][0])} ↗</a>`).join('')}</div>`:''}${result.actions?.length?`<div class="mentor-actions">${result.actions.map(a=>`<a href="${a.href}">${esc(a.label)} →</a>`).join('')}</div>`:''}</article>`}
 catch(error){box.innerHTML=`<p class="mentor-analysis-error" role="alert">${esc(error.message||'No pude revisar estos datos. Revisa los valores e inténtalo de nuevo.')}</p>`}
}
function mentorReply(question){if(typeof MentorAssistant==='undefined'){const q=question.toLocaleLowerCase('es');const text=/siguiente|estudiar|m[oó]dulo|ruta/.test(q)?`Tu siguiente paso es el módulo ${nextModule().id}: ${nextModule().title}. ${nextModule().description}`:/tradici|t[ií]tul|vivienda usada|comprar/.test(q)?'Antes de comprar vivienda usada, solicita un Certificado de Tradición y Libertad reciente y pide una revisión jurídica independiente.':'No tengo suficiente información para darte una recomendación responsable.';latestMentorResponse={text,sources:[],actions:[]};return text}latestMentorResponse=MentorAssistant.reply(question,state.chat,state.profile);return latestMentorResponse.text}
function mentorContainsSensitiveData(value){
 const text=String(value||'');
 const identity=/(?:c[eé]dula|\bcc\b|\bnit\b|matr[ií]cula inmobiliaria|folio de matr[ií]cula|n[uú]mero de cuenta|cuenta bancaria)[^\d]{0,14}\d[\d .-]{4,22}\d|\d[\d .-]{4,22}\d[^\d]{0,14}(?:c[eé]dula|\bcc\b|\bnit\b|matr[ií]cula inmobiliaria|folio de matr[ií]cula|n[uú]mero de cuenta|cuenta bancaria)/i;
 const contact=/(?:correo|e-?mail)\s*(?:es|:)?\s*[\w.+-]+@[\w.-]+\.[a-z]{2,}|(?:celular|tel[eé]fono|m[oó]vil)\D{0,10}(?:\+?57\D*)?3\d(?:[\d .-]{7,12}\d)/i;
 const credential=/\b(?:mi\s+)?(?:clave|contrase(?:n|ñ)a|password|token|c[oó]digo\s+(?:otp|de verificaci[oó]n|de seguridad))\s*(?:es|:|#)\s*\S{4,}/i;
 return identity.test(text)||contact.test(text)||credential.test(text);
}
async function sendMentorQuestion(q,useAi=false,webSearch=false){if(!q.trim())return;const cleanQuestion=q.trim();let answer;const outboundMessages=[cleanQuestion,...state.chat.slice(-4).map(message=>message.text||'')];const sensitiveFound=outboundMessages.some(mentorContainsSensitiveData);if(useAi&&sensitiveFound){answer={text:'No envié esta consulta ni los mensajes previos a la IA porque detecté datos que podrían identificarte o permitir acceso a una cuenta. Elimina cédulas, matrículas, números de cuenta, correos, teléfonos, claves o códigos y vuelve a preguntar si quieres usar IA. Esta conversación permanece en este dispositivo hasta que la borres.',mode:'local',links:[],sources:[],actions:[],challenge:null,challengeAnswered:false}}else if(useAi){try{const response=await fetch('/api/mentor',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({question:cleanQuestion,webSearch,history:(webSearch?state.chat.filter(m=>m.role==='user'||(m.role==='mentor'&&m.links?.length)):state.chat).slice(-4).map(({role,text})=>({role,text}))})});const payload=await response.json();if(!response.ok)throw new Error(payload.error||'La IA no está disponible.');answer={text:payload.text,mode:'ia',checkedAt:payload.checkedAt||null,links:payload.links||[],sources:[],actions:[],challenge:null,challengeAnswered:false}}catch(error){if(webSearch){answer={text:error.message,mode:'notice',links:[],sources:[],actions:[],challenge:null,challengeAnswered:false}}else{answer=MentorAssistant.reply(cleanQuestion,state.chat,state.profile);answer.mode='local';answer.text=`No se pudo usar la IA (${error.message}). Te respondo con el mentor local:\n\n${answer.text}`}}}else{mentorReply(cleanQuestion);answer=latestMentorResponse||{text:'No tengo suficiente información para responder responsablemente.',sources:[],actions:[]};answer.mode='local'}if(answer.challengeAnswered){const previousChallenge=[...state.chat].reverse().find(message=>message.role==='mentor'&&message.challenge&&!message.challengeAnswered);if(previousChallenge)previousChallenge.challengeAnswered=true}state.chat.push({role:'user',text:cleanQuestion},{role:'mentor',text:answer.text,mode:answer.mode||'local',links:answer.links||[],sources:answer.sources||[],checkedAt:answer.checkedAt||null,actions:answer.actions||[],challenge:answer.challenge||null,challengeAnswered:Boolean(answer.challengeAnswered)});if(state.chat.length>60)state.chat=state.chat.slice(-60);persist();render();$('#chat-messages')?.scrollTo(0,99999)}
async function refreshMentorAiStatus(){const checkbox=$('#mentor-ai-optin');const status=$('#mentor-ai-status');const webCheckbox=$('#mentor-web-search');const webStatus=$('#mentor-web-status');if(!checkbox||!status)return;checkbox.disabled=true;if(webCheckbox)webCheckbox.disabled=true;try{const response=await fetch('/api/status',{cache:'no-store',headers:{Accept:'application/json'}});const result=await response.json();if(!response.ok||typeof result.aiConfigured!=='boolean')throw new Error('estado no disponible');checkbox.disabled=!result.aiConfigured;const supportsGemini=result.provider==='gemini';if(webCheckbox)webCheckbox.disabled=!result.aiConfigured||!supportsGemini;if(webStatus)webStatus.textContent=!supportsGemini?'La búsqueda web de esta integración requiere Gemini.':result.aiConfigured?'Google Search está disponible; solo se usa si activas esta casilla.':'Conecta Gemini para habilitar búsqueda web.';const keySetup=$('#mentor-key-setup');if(keySetup)keySetup.open=!result.aiConfigured;status.textContent=result.aiConfigured?'Gemini listo en el servidor.':'Configura GEMINI_API_KEY en el servidor para activar IA; el mentor local funciona mientras tanto.'}catch{checkbox.disabled=true;if(webCheckbox)webCheckbox.disabled=true;if(webStatus)webStatus.textContent='No se detectó el servidor con IA.';status.textContent='No se detectó el servidor con IA. El mentor local sigue disponible.'}}
function render(){updateShell();const container=$('#page-content');const hash=location.hash.slice(1);if(currentPage==='leccion'&&(/^section-\d+$/.test(hash)||hash==='lesson-quiz')){lastRenderedHash=hash;return}const routeChanged=lastRenderedHash!==hash;lastRenderedHash=hash;if(hash.startsWith('leccion/')){currentPage='leccion';currentLesson=Number(hash.split('/')[1]);container.innerHTML=lessonPage(currentLesson)}else{if(hash==='diagnostico')currentPage='diagnostico';else if(hash==='ruta')currentPage='ruta';else if(hash==='herramientas'||hash.startsWith('herramientas/')){currentPage='herramientas';const requestedTool=hash.split('/')[1];if(['compra','creditos','propiedades','inversion'].includes(requestedTool))activeTool=requestedTool;}else if(hash==='glosario')currentPage='glosario';else if(hash==='mentor')currentPage='mentor';else currentPage='inicio';container.innerHTML=({diagnostico:diagnosticPage,inicio:dashboard,ruta:routePage,herramientas:toolsPage,glosario:glossaryPage,mentor:mentorPage})[currentPage]()}if(routeChanged)window.scrollTo?.({top:0,left:0,behavior:'instant'});updateShell();if(currentPage==='mentor')refreshMentorAiStatus();$('#sidebar').classList.remove('open');$('#mobile-menu').setAttribute('aria-expanded','false');$('#mobile-menu').setAttribute('aria-label','Abrir menú');}
function awardIfEarned(id){const achieved=[];if(completedCount()>=1&&!state.achievements.includes('primer-paso')){state.achievements.push('primer-paso');achieved.push('🏡 Primer paso: completaste tu primera lección.')};if(completedCount()>=5&&!state.achievements.includes('mitad-ruta')){state.achievements.push('mitad-ruta');achieved.push('✦ Media ruta: ya dominas cinco módulos.')};if(completedCount()===10&&!state.achievements.includes('ruta-completa')){state.achievements.push('ruta-completa');achieved.push('🏆 Ruta completa: integraste los diez módulos.')};if((state.scores[id]||0)===100&&!state.achievements.includes(`perfecto-${id}`)){state.achievements.push(`perfecto-${id}`);achieved.push(`✨ Módulo ${id}: evaluación perfecta.`)}return achieved}
function submitQuiz(form){
 const id=Number(form.dataset.module),l=MODULES[id-1].lesson,questions=[{answer:l.answer},...LESSON_EXTRAS[id].questions],fd=new FormData(form);
 const rawAnswers=questions.map((_,i)=>fd.get(`answer-${i}`));
 if(rawAnswers.some(answer=>answer===null)){toast('Responde las dos preguntas para continuar.');return}
 const answers=rawAnswers.map(Number);
 if(answers.some((answer,i)=>!Number.isInteger(answer)||answer<0||answer>=((i===0?l.options:LESSON_EXTRAS[id].questions[i-1].options).length))){toast('Revisa las opciones seleccionadas.');return}
 const correctCount=answers.reduce((count,answer,index)=>count+(answer===questions[index].answer?1:0),0),correct=correctCount>=1,old=state.attempts[id]?.count||0,score=Math.round(correctCount/questions.length*100);
 state.attempts[id]={answers,correct,correctCount,count:old+1};state.scores[id]=Math.max(state.scores[id]||0,score);state.lessonHistory.push({id,at:new Date().toISOString(),correct});
 if(correct&&!state.completed.includes(id))state.completed.push(id);state.completed.sort((a,b)=>a-b);const awards=correct?awardIfEarned(id):[];persist();render();
 if(awards.length)toast(awards[0]);else toast(correct?`Evaluación aprobada: ${correctCount} de 2 correctas.`:'Respuesta revisada. Repasa y vuelve a intentarlo.');
 if(correct)$('#lesson-quiz')?.scrollIntoView({behavior:'smooth',block:'center'})
}function saveCase(id){state.caseNotes=state.caseNotes||{};state.caseNotes[id]=$('#case-answer').value;persist();toast('Notas guardadas en este dispositivo.')}
function openProfile(){const modal=$('#onboarding-modal');$('#onboarding-title').textContent=state.profile?'Actualiza tu ruta.':'Empecemos por ti.';$('#user-name').value=state.profile?.name||'';$$('input[name="objective"]').forEach(el=>el.checked=el.value===(state.profile?.objective||'vivir'));$('#horizon').value=state.profile?.horizon||'aprendiendo';$('#level').value=state.profile?.level||'principiante';$('#monthly-income').value=state.profile?.income||'';$('#monthly-savings').value=state.profile?.savings||'';if(!modal.open)modal.showModal()}
document.addEventListener('click',e=>{const clearChat=e.target.closest('[data-clear-chat]');if(clearChat){state.chat=[];persist();render();toast('Conversación limpiada.');return}const exportBtn=e.target.closest('[data-export-learning]');if(exportBtn){exportLearningData();return}const importBtn=e.target.closest('[data-import-learning]');if(importBtn){$('#learning-backup-file')?.click();return}const bookmark=e.target.closest('[data-bookmark]');if(bookmark){toggleBookmark(Number(bookmark.dataset.bookmark));return}const nav=e.target.closest('[data-page-link]');if(nav){e.preventDefault();location.hash=nav.dataset.pageLink;return}const open=e.target.closest('[data-open-lesson]');if(open){location.hash=`leccion/${open.dataset.openLesson}`;return}const next=e.target.closest('[data-next-lesson]');if(next){location.hash=`leccion/${next.dataset.nextLesson}`;return}const tab=e.target.closest('[data-tool]');if(tab){activeTool=tab.dataset.tool;render();return}const calc=e.target.closest('[data-calculate]');if(calc){if(calc.dataset.calculate==='buy')calcBuy();if(calc.dataset.calculate==='add-loan')addLoan();if(calc.dataset.calculate==='add-property')addProperty();if(calc.dataset.calculate==='investment')calcInvestment();return}const remLoan=e.target.closest('[data-remove-loan]');if(remLoan){state.loans=state.loans.filter(x=>x.id!==Number(remLoan.dataset.removeLoan));persist();$('#loans-table').innerHTML=loanTable();return}const remProp=e.target.closest('[data-remove-property]');if(remProp){state.properties=state.properties.filter(x=>x.id!==Number(remProp.dataset.removeProperty));persist();$('#properties-table').innerHTML=propertyTable();return}const letter=e.target.closest('[data-letter]');if(letter){activeGlossaryLetter=letter.dataset.letter;const query=$('#glossary-search')?.value||'';const filtered=TERMS.filter(t=>(!activeGlossaryLetter||t[0].toLocaleUpperCase('es').startsWith(activeGlossaryLetter))&&t[0].toLocaleLowerCase('es').includes(query.toLocaleLowerCase('es')));$('#glossary-entries').innerHTML=glossaryCards(filtered);$$('[data-letter]').forEach(b=>b.classList.toggle('active',b.dataset.letter===activeGlossaryLetter));return}const sug=e.target.closest('[data-suggestion]');if(sug){sendMentorQuestion(sug.dataset.suggestion);return}const save=e.target.closest('[data-save-case]');if(save){saveCase(Number(save.dataset.saveCase));return}});
document.addEventListener('submit',e=>{if(e.target.id==='mentor-key-form'){e.preventDefault();configureMentorKey(e.target)}if(e.target.id==='diagnostic-form'){e.preventDefault();submitDiagnostic(e.target)}if(e.target.id==='mentor-case-form'){e.preventDefault();submitMentorScenario(e.target)}if(e.target.id==='quiz-form'){e.preventDefault();submitQuiz(e.target)}if(e.target.id==='mentor-form'){e.preventDefault();const form=e.target;const button=form.querySelector('button[type="submit"]');button.disabled=true;button.textContent='Pensando…';sendMentorQuestion($('#mentor-input').value,$('#mentor-ai-optin')?.checked,$('#mentor-web-search')?.checked).finally(()=>{button.disabled=false;button.textContent='Consultar ↑'})}if(e.target.id==='onboarding-form'){e.preventDefault();const f=new FormData(e.target);const profile={name:String(f.get('name')||'').trim(),objective:f.get('objective'),horizon:f.get('horizon'),level:f.get('level'),income:Number(f.get('income'))||null,savings:Number(f.get('savings'))||null};if(!profile.name){$('#user-name').focus();return}state.profile=profile;persist();$('#onboarding-modal').close();render();toast('Tu ruta personalizada está lista.');}});
document.addEventListener('change',e=>{if(e.target.id==='learning-backup-file'){void importLearningBackupFile(e.target.files?.[0]);e.target.value='';return}if(e.target.id==='mentor-analysis-type')$$('[data-case-fields]').forEach(group=>group.classList.toggle('hidden',group.dataset.caseFields!==e.target.value))});document.addEventListener('input',e=>{if(e.target.id==='global-search-input'){const box=$('#global-search-results');box.innerHTML=globalSearchResults(e.target.value);box.classList.toggle('hidden',!e.target.value.trim());return}if(e.target.id==='glossary-search'){const query=e.target.value.toLocaleLowerCase('es');$('#glossary-entries').innerHTML=glossaryCards(TERMS.filter(t=>(!activeGlossaryLetter||t[0].toLocaleUpperCase('es').startsWith(activeGlossaryLetter))&&t[0].toLocaleLowerCase('es').includes(query)))}});
document.addEventListener('keydown',e=>{if(e.target.id==='global-search-input'&&e.key==='Enter'){const first=$('#global-search-results a');if(first){e.preventDefault();location.hash=first.getAttribute('href');$('#global-search-input').value='';$('#global-search-results').classList.add('hidden')}}if(e.key==='Escape'&&e.target.id==='global-search-input')$('#global-search-results').classList.add('hidden');if(e.key==='Escape'&&$('#sidebar').classList.contains('open')){$('#sidebar').classList.remove('open');$('#mobile-menu').setAttribute('aria-expanded','false');$('#mobile-menu').setAttribute('aria-label','Abrir menú')}});document.addEventListener('click',e=>{if(!e.target.closest('.global-search'))$('#global-search-results')?.classList.add('hidden')});window.addEventListener('hashchange',render);$('#mobile-menu').addEventListener('click',()=>{const open=$('#sidebar').classList.toggle('open');$('#mobile-menu').setAttribute('aria-expanded',String(open));$('#mobile-menu').setAttribute('aria-label',open?'Cerrar menú':'Abrir menú')});$('#profile-button').addEventListener('click',openProfile);$('#top-avatar').addEventListener('click',openProfile);
function mergeLearningPayload(local,remote){
 const scores={...(local.scores||{}),...(remote.scores||{})};
 for(const key of Object.keys(local.scores||{}))scores[key]=Math.max(Number(local.scores[key])||0,Number(remote.scores?.[key])||0);
 const attempts={...(local.attempts||{}),...(remote.attempts||{})};
 const history=[...(local.lessonHistory||[]),...(remote.lessonHistory||[])];
 const uniqueHistory=[...new Map(history.map(item=>[`${item.id}:${item.at}:${item.correct}`,item])).values()];
 return {profile:remote.profile||local.profile,completed:[...new Set([...(local.completed||[]),...(remote.completed||[])])].sort((a,b)=>a-b),scores,attempts,lessonHistory:uniqueHistory,achievements:[...new Set([...(local.achievements||[]),...(remote.achievements||[])])],bookmarks:[...new Set([...(local.bookmarks||[]),...(remote.bookmarks||[])])],diagnostic:remote.diagnostic||local.diagnostic||null,caseNotes:{...(local.caseNotes||{}),...(remote.caseNotes||{})},activeModule:remote.activeModule||local.activeModule||1,lastVisit:remote.lastVisit||local.lastVisit||null};
}
async function handleAuthState(user){
 const screen=$('#auth-screen'),signOut=$('#sign-out-button'),message=$('#auth-message');
 if(!user){document.body.classList.add('auth-required');if(screen)screen.classList.remove('hidden');if(signOut)signOut.classList.add('hidden');if(message)message.textContent='Conexión lista. Inicia sesión o crea una cuenta para guardar tu avance.';return}
 document.body.classList.remove('auth-required');if(signOut)signOut.classList.remove('hidden');
 try{
  const remote=await window.MentorAuth.loadProgress();
  if(remote){state={...structuredClone(DEFAULT_STATE),...remote,chat:[],properties:[],loans:[]};if(legacyLearningState&&confirm('Ya hay avance en tu cuenta. ¿Quieres combinarlo con el avance académico antiguo de este navegador? Se fusionarán módulos, resultados, notas y marcadores.')){state={...state,...mergeLearningPayload(learningPayload(legacyLearningState),remote)};await window.MentorAuth.saveProgress(learningPayload())}}
  else if(legacyLearningState&&confirm('¿Quieres importar a esta cuenta el avance académico guardado anteriormente en este navegador? Se migrarán perfil educativo, evaluaciones, notas y marcadores. No se copiarán cifras financieras, simuladores ni conversaciones.')){
   state={...structuredClone(DEFAULT_STATE),...learningPayload(legacyLearningState),chat:[],properties:[],loans:[]};await window.MentorAuth.saveProgress(learningPayload());
  }else state=structuredClone(DEFAULT_STATE);
  try{localStorage.removeItem(STORAGE_KEY)}catch{}
  if(screen)screen.classList.add('hidden');
  $('.saved-state').textContent='Progreso en tu cuenta';
  render();if(!state.profile)openProfile();
 }catch(error){document.body.classList.add('auth-required');if(message)message.textContent=`No se pudo cargar tu progreso: ${error.message}`;if(signOut)signOut.classList.remove('hidden')}
}

if(document.body){
$('#auth-switch').addEventListener('click',()=>{
 authMode=authMode==='signin'?'signup':'signin';
 const submit=$('#auth-submit');const password=$('#auth-password');
 submit.textContent=authMode==='signup'?'Crear cuenta':'Iniciar sesión';
 $('#auth-title').textContent=authMode==='signup'?'Crea tu cuenta.':'Aprende a tu ritmo.';
 $('#auth-switch').textContent=authMode==='signup'?'¿Ya tienes cuenta? Iniciar sesión':'¿No tienes cuenta? Crear cuenta';
 password.autocomplete=authMode==='signup'?'new-password':'current-password';
});
$('#auth-form').addEventListener('submit',async event=>{
 event.preventDefault();const button=$('#auth-submit'),message=$('#auth-message');
 button.disabled=true;message.textContent='Conectando…';
 try{
  const email=$('#auth-email').value.trim(),password=$('#auth-password').value;
  const result=authMode==='signup'?await window.MentorAuth.signUp(email,password):(await window.MentorAuth.signIn(email,password),null);
  if(authMode==='signup'&&!result.session){message.textContent='Cuenta creada. Revisa tu correo para confirmar la dirección y luego inicia sesión.';return}
  message.textContent='Sesión iniciada. Cargando tu progreso…';
 }catch(error){message.textContent=error.message||'No se pudo completar la solicitud.'}
 finally{button.disabled=false}
});
$('#sign-out-button').addEventListener('click',async()=>{try{await window.MentorAuth.signOut();state=structuredClone(DEFAULT_STATE);document.body.classList.add('auth-required');render()}catch(error){toast(`No se pudo cerrar sesión: ${error.message}`)}});
window.addEventListener('mentor-progress-saved',()=>{$('.saved-state').textContent='Progreso guardado en tu cuenta'});
window.addEventListener('mentor-progress-error',event=>{ $('.saved-state').textContent='No se pudo sincronizar';toast(`Error al guardar: ${event.detail}`)});
document.body.classList.add('auth-required');
if(window.MentorAuth){window.MentorAuth.onChange(handleAuthState);window.MentorAuth.ready.then(handleAuthState).catch(error=>{$('#auth-message').textContent=error.message;$('#auth-submit').disabled=true})}
}else{render()}


